import json,copy
from pathlib import Path
from content_helper import case,rows
rows.clear()
case('P286','A_04609',['投掷标枪','观察持枪、后引、身体转动和前送的连续协调，不指定唯一运动技术。','手对标枪的支撑、加速和释放应相关，枪身应保持连续结构。','若标枪脱手，运动应与释放方向和重力相容，不要求整段远距离飞行可见。','若有随动或落地，观察惯性与支撑，不推断画面外命中或距离。','仅显示后引等准备动作而实际投掷不足以评价时选择无法判断。','人体投掷、标枪释放与可见飞行'],['Throw a javelin','Consider continuous coordination of grip, withdrawal, body rotation, and forward delivery without prescribing one technique.','Support, acceleration, and release should correspond, with continuous javelin structure.','If released, motion should fit release direction and gravity. The entire long flight need not be visible.','If follow-through or landing is shown, consider inertia and support without inferring off-screen distance or success.','Choose unable to judge if only withdrawal or other preparation is shown and actual throwing cannot be assessed.','Body throwing, javelin release, and visible flight'])
case('P287','A_04476',['投出保龄球','观察双手承球到单手摆臂、步伐和下放释放的协调。','球应在持握时受手支撑，脱手时刻与前摆及球道接触应相关。','球可向前滚动，不要求腾空很高或短片内撞到球瓶。','若球在道上继续运动或人随挥，观察接触和惯性，不推断画面外击瓶结果。','只有抱球或后摆准备，实际投出不足以评价时选择无法判断。','人体步伐摆臂、保龄球释放与球道接触'],['Deliver a bowling ball','Consider transfer from two-hand support to arm swing, stepping, and low release.','Hands should support the held ball, with separation related to forward swing and lane contact.','The ball may roll forward. High airborne motion or pin impact within the clip is not required.','On continuing lane motion or follow-through, consider contact and inertia without inferring off-screen pin results.','Choose unable to judge if only holding or backswing preparation is shown and actual delivery cannot be assessed.','Body stepping and swing, bowling-ball release, and lane contact'])
case('P288','A_04287',['晃动平底锅翻饼','观察握柄、手腕提送与上身平衡。','锅面作用、饼离锅和回落时刻应与手臂动作相容。','整张饼可滑动、弯曲或空中翻转，不要求像液体一样流出或出现固定高度。','若饼落回锅面，观察重力、柔性及再次接触，不要求翻转必须成功才可给合理分。','只有端锅准备，实际翻动不足以评价时选择无法判断。','人体控锅、饼的离锅翻转与回落接触'],['Toss a pancake with a frying pan','Consider handle grip, wrist delivery, and upper-body balance.','Pan action, pancake departure, and return timing should be compatible with arm motion.','The whole pancake may slide, bend, or rotate in flight without liquid-like outflow or a prescribed height.','On return, consider gravity, flexibility, and renewed contact. A successful flip is not required for plausible physics.','Choose unable to judge if only holding preparation is shown and actual tossing cannot be assessed.','Pan control, pancake departure and rotation, and return contact'])
for sid,mid in [('P289','A_04061'),('P291','A_03943')]:
 c=copy.deepcopy(next(x for x in rows if x['sample_id']=='P288'));c.update(sample_id=sid,media_id=mid,shared_task_basis='与P288同为平底锅翻整张饼，锅材质和饼色不改变本条物理作用条件');rows.append(c)
case('P290','A_03997',['用剑玉托接系绳小球','观察握持木柄、抛起或提拉和对准接球位置的协调。','球与柄之间的绳长约束应合理，接触时应对应手柄的承接位置。','球可在松绳时运动或绳张紧时改变方向，不能把它当作无绳自由球要求评价。','若接住、错过或摆回，观察重力、绳约束和碰撞，不要求每次接球成功。','只有准备握持，实际球柄绳运动不足以评价时选择无法判断。','人体控柄、系绳球运动与承接接触'],['Catch a tethered kendama ball','Consider handle grip, tossing or lifting, and alignment with the receiving position.','String-length constraints should be plausible, with catches corresponding to handle contact locations.','The ball may move with slack or change direction under tension. Do not assume an untethered free ball.','On catching, missing, or swinging back, consider gravity, string constraints, and collision without requiring success every time.','Choose unable to judge if only preparatory grip is shown and actual ball–handle–string motion cannot be assessed.','Handle control, tethered-ball motion, and receiving contact'])
case('P292','A_03664',['晃锅翻动块状食材','观察握柄、前后提送与手臂躯干协调。','食材与锅面的承托、离开和再接触应与锅体动作相关。','块状食材可滑动、分散或部分腾空，不要求全部一起跳出或组成整张饼。','若食材落回或蒸汽上升，观察重力、碰撞及气体扩散。','只有持锅准备，实际翻动不足以评价时选择无法判断。','人体控锅、块状食材运动与回锅碰撞'],['Toss chunky food in a pan','Consider handle grip, forward–back delivery, and arm–torso coordination.','Food support, separation, and renewed contact should relate to pan action.','Chunks may slide, scatter, or partly lift without all leaving together or forming one pancake.','On return or rising steam, consider gravity, collisions, and gas dispersal.','Choose unable to judge if only holding preparation is shown and actual tossing cannot be assessed.','Pan control, chunky-food motion, and returning collisions'])
case('P293','A_03453',['朝墙面投掷药球','观察双手推送、躯干和下肢承力及回接准备。','球的加速与脱手应对应双手前送，若碰墙，球的变化应对应墙面接触。','球可飞行并反弹，不凭表面外观指定精确重量或要求明显压扁。','若回接或落下，观察重力、手部缓冲和支撑，不要求完整来回都可见。','只有抱球准备，实际投掷不足以评价时选择无法判断。','人体双手投送、药球墙面作用与回接支撑'],['Throw a medicine ball toward a wall','Consider two-hand delivery, trunk and leg effort, and receiving preparation.','Acceleration and release should correspond to forward hand action. Any rebound should relate to wall contact.','The ball may fly and rebound without a prescribed exact mass or obvious flattening.','On catching or falling, consider gravity, hand cushioning, and support. A complete round trip need not be visible.','Choose unable to judge if only holding preparation is shown and actual throwing cannot be assessed.','Two-hand delivery, medicine-ball wall action, and receiving support'])
case('P294','A_03598',['用手托持和移动橙子','观察手指承托、手腕抬降及身体协调。','持握时橙子应有合理手部支撑，若脱手则按实际自由运动评价。','橙子可转动、升降或短暂离手，不要求其剥皮、变形或持续悬空。','若下落、重新接住或继续持有，观察重力、接触与缓冲，不推断隐藏支架。','手果关系被遮挡，实际承托或脱手运动不足以评价时选择无法判断。','手部承托、橙子升降与重力接触'],['Support and move an orange by hand','Consider finger support, wrist lifting and lowering, and body coordination.','A held orange should have plausible hand support. Assess actual free motion if released.','The orange may rotate, rise, lower, or briefly leave the hand without peeling, deformation, or sustained levitation.','On falling, catching, or continued holding, consider gravity, contact, and cushioning without inferring hidden supports.','Choose unable to judge if hand–fruit relations are obscured and support or released motion cannot be assessed.','Hand support, orange elevation changes, and gravity-related contact'])
case('P295','A_04277',['在室内练习区挥动高尔夫球杆','观察握杆、肩髋转动、重心转移和随挥。','人杆连接与杆头通过击球区域的轨迹应连续，若有实体球，按实际接触评价。','球杆可快速转动，背景屏幕图像不等于实体球的可见飞行，也不要求室内出现草屑。','若球接触幕布或人结束随挥，观察可见碰撞与平衡，不推断模拟器数值。','只有瞄准或上杆准备，实际挥动不足以评价时选择无法判断。','人体转动、室内球杆轨迹与击球区作用'],['Swing a golf club in an indoor practice area','Consider grip, shoulder–hip rotation, weight transfer, and follow-through.','Hand–club connection and head passage through the hitting area should remain continuous. Assess physical-ball contact if visible.','The club may rotate quickly. Screen imagery is not a visible physical-ball flight, and indoor turf spray is not required.','On ball–screen contact or completed follow-through, consider visible collision and balance without inferring simulator numbers.','Choose unable to judge if only aiming or backswing preparation is shown and actual swinging cannot be assessed.','Body rotation, indoor club trajectory, and hitting-area action'])
case('P296','A_03903',['挥动网球拍击球','观察握拍、肩臂挥动、转体与脚部支撑。','拍面与球相遇的时刻应和球速或方向变化相符，握持应连续。','球可快速离拍，不要求细微球拍弹性或旋转清晰可辨。','若球继续飞行或人物随挥，观察可见连续性，不推断画面外落点与得分。','只有准备挥拍或关键球拍作用不可见时选择无法判断。','人体挥拍、网球拍球接触与球体飞行'],['Strike a tennis ball with a racket','Consider grip, arm swing, torso rotation, and foot support.','Racket–ball encounter timing should match speed or direction changes, with continuous grip.','The ball may leave rapidly. Fine racket elasticity or spin need not be resolved.','On visible flight or follow-through, consider continuity without inferring off-screen landing or score.','Choose unable to judge if only preparation is shown or crucial racket–ball action is hidden.','Body swing, tennis racket–ball contact, and ball flight'])
c=copy.deepcopy(json.loads(Path(__file__).with_name('batch_29.json').read_text())[2]);assert c['sample_id']=='P216';c.update(sample_id='P297',media_id='A_04035',shared_task_basis='与P216同为球座上高尔夫球的挥杆击打，球色不改变接触和飞行条件');rows.append(c)
case('P298','A_03701',['挥拍击打壁球','观察持拍、低位迎球、脚步及躯干协调。','拍面与球相遇应对应球速方向变化，球与墙地的反弹按可见接触评价。','小球可快速飞行或弹跳，不要求每次完整往返和细微旋转可见。','若球反弹或人物随挥，观察碰撞、重力与身体平衡，不推断画面外击球。','只有迎球准备，实际击球或反弹关系不足以评价时选择无法判断。','人体低位挥拍、壁球接触与墙地反弹'],['Strike a squash ball','Consider grip, low reaching, footwork, and torso coordination.','Racket encounters should relate to ball speed or direction changes. Assess wall and floor rebounds at visible contacts.','The small ball may fly or bounce rapidly without every full return or fine spin being visible.','On rebounds or follow-through, consider collision, gravity, and balance without inferring off-screen strikes.','Choose unable to judge if only readiness is shown and actual striking or rebound relations cannot be assessed.','Low body swing, squash-ball contact, and wall–floor rebounds'])
case('P299','A_04490',['用球杆击打台球母球','观察俯身、架杆手固定与后手沿杆导向的协调。','杆头与白色母球接触应对应球的启动，架杆位置与球杆结构应连续。','母球可在台面滚动，不要求跳球、进袋或短片内碰到其他球。','若碰球、碰库或继续滚动，观察可见碰撞与减速，不推断画面外结果。','只有瞄准或试杆，实际击球不足以评价时选择无法判断。','人体架杆推送、杆头母球接触与台面滚动'],['Strike a billiard cue ball with a cue','Consider leaning, bridge-hand support, and rear-hand shaft guidance.','Tip contact should correspond to cue-ball onset, with continuous bridge placement and cue structure.','The cue ball may roll across the cloth. Jumping, pocketing, or another-ball collision within the clip is not required.','On visible ball or cushion collision or continuing roll, consider collision and deceleration without inferring off-screen results.','Choose unable to judge if only aiming or practice strokes are shown and actual striking cannot be assessed.','Body bridge and delivery, tip–cue-ball contact, and tabletop rolling'])
c=copy.deepcopy(next(x for x in json.loads(Path(__file__).with_name('batch_29.json').read_text()) if x['sample_id']=='P218'));c.update(sample_id='P300',media_id='A_04488',shared_task_basis='与P218同为草面球位挥杆，服装与镜头远近不改变人体球杆球位作用要求');rows.append(c)
Path(__file__).with_name('batch_33.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2))
